const int maxn = 3e5 + 5;
int a[maxn];
int pmod1[maxn], pmod2[maxn];
const int b1 = 31, b2 = 37;
const int mod1 = 1e9 + 7, mod2 = 1e9 + 9;
struct Node {
    int h1, h2;
    int len;
};
Node seg[4 * maxn];
Node operator+(const Node &a, const Node &b) {
    Node c;
    c.h1 = (1LL * a.h1 * pmod1[b.len] + b.h1) % mod1;
    c.h2 = (1LL * a.h2 * pmod2[b.len] + b.h2) % mod2;
    c.len = a.len + b.len;
    return c;
}
void update(int id, int l, int r, int pos) {
    if (l == r) {
        seg[id] = {0, 0, 0};
        return;
    }
    int mid = (l + r) / 2;
    if (pos <= mid)
        update(2 * id, l, mid, pos);
    else
        update(2 * id + 1, mid + 1, r, pos);
    seg[id] = seg[2 * id] + seg[2 * id + 1];
}
int find_kth(int u, int l, int r, int k) {
    if (l == r) return l;
    int mid = (l + r) / 2;
    if (seg[2 * u].len >= k) {
        return find_kth(2 * u, l, mid, k);
    }
    return find_kth(2 * u + 1, mid + 1, r, k - seg[2 * u].len);
}
Node query(int id, int l, int r, int u, int v) {
    if (l > v || r < u) return {0, 0, 0};
    if (l >= u && r <= v) return seg[id];
    int mid = (l + r) / 2;
    return query(2 * id, l, mid, u, v) + query(2 * id + 1, mid + 1, r, u, v);
}
void build(int id, int l, int r) {
    if (l == r) {
        seg[id] = {a[l], a[l], 1};
        return;
    }
    int mid = (l + r) / 2;
    build(2 * id, l, mid);
    build(2 * id + 1, mid + 1, r);
    seg[id] = seg[2 * id] + seg[2 * id + 1];
}
int main() {    
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    string s;
    cin >> s;
    debug(s);
    int n, q;
    n = s.size();
    pmod1[0] = pmod2[0] = 1;
    for (int i = 1; i <= n; i++) {
        pmod1[i] = (1LL * pmod1[i - 1] * b1) % mod1;
        pmod2[i] = (1LL * pmod2[i - 1] * b2) % mod2;
    }
    cin >> q;
    debug(q);
    for(int i = 1; i <= n; i++) {
        a[i] = s[i - 1] - '0' + 1;
    }
    build(1, 1, n);
    while(q--) {
        char t;
        cin >> t;
        debug(t);
        if(t == '?') {
            int l, r, k;
            cin >> l >> r >> k;
            int l1 = find_kth(1, 1, n, l);
            int r1 = find_kth(1, 1, n, l + k - 1);
            int l2 = find_kth(1, 1, n, r);
            int r2 = find_kth(1, 1, n, r + k - 1);

            Node h1 = query(1, 1, n, l1, r1);
            Node h2 = query(1, 1, n, l2, r2);
            cout << (h1.h1 == h2.h1 && h1.h2 == h2.h2 ? "YES" : "NO") << '\n';
        } else {
            int pos;
            cin >> pos;
            int real_pos = find_kth(1, 1, n, pos);
            update(1, 1, n, real_pos);
        }
    }
}